from rendu import Point
p=Point(9)
p.h('9.a — Choisir la référence adaptée à la question')
p.p('Un pied plat souple indolore et une maladie de Dupuytren typique se caractérisent d’abord cliniquement : l’imagerie systématique n’apporte pas la réponse attendue. À l’inverse, une fracture du radius exige des clichés pour caractériser le déplacement ; la scoliose se mesure sur le rachis entier debout et l’XLH exige un bilan biologique causal.', ['pa82-plat-europe-imagerie','pa82-dupuytren-examens','pa82-radius-imagerie','p82-scoliose-radio','p82-xlh-mecanisme-bilan'])
p.h('9.b — Première intention : formuler la demande et interpréter le résultat')
p.tableau(['Prescription ciblée', 'Lecture attendue', 'Conséquence'], [
 [('Radius traumatique : radiographies du poignet de face et de profil.','pa82-radius-imagerie'),('Décrire hauteur radiale, inclinaison, variance ulnaire, bascule dorsale et éventuelle marche articulaire.','pa82-radius-imagerie'),('Relier déplacement à peau, nerfs, vaisseaux et fonction antérieure ; les mesures radiographiques ne remplacent pas les priorités de réduction et de protection.',['p82-radius','pa82-radius-but'])],
 [('Hallux valgus : radiographies du pied en charge dans au moins deux plans selon AWMF 2026.','pa82-hallux-imagerie'),('Mesurer les axes et rechercher la composante articulaire ; HVA inférieur à quinze degrés et angle intermétatarsien inférieur à neuf degrés sont les repères normaux rapportés par la revue.','pa82-hallux-normalite'),('Confronter les angles à la douleur, à la réductibilité et à la mobilité ; l’hétérogénéité des classifications interdit de décider sur une catégorie seule.',['pa82-hallux-normalite','pa82-hallux-examen'])],
 [('Pied plat douloureux : envisager face et profil en charge, avec incidence oblique ; aucun cliché systématique pour un pied souple indolore.','pa82-plat-europe-imagerie'),('Rechercher une cause à la douleur ou à la rigidité plutôt que confirmer un simple aspect plat.',['pa82-plat-europe-imagerie','p82-plat-examen']),('Une rigidité ou une asymétrie motive l’évaluation spécialisée ; un pied souple indolore relève de l’information et de la surveillance clinique.',['pa82-plat-europe-imagerie','p82-plat-examen'])],
 [('Désaxation pathologique suspectée : cliché frontal des membres inférieurs entiers en charge, rotules vers l’avant, inégalité de longueur corrigée.',['pa82-genou-imagerie','pa82-genou-axe-mecanique']),('Tracer l’axe mécanique du centre de la tête fémorale au centre du talus ; il passe normalement au centre du genou.','pa82-genou-axe-mecanique'),('Quantifier l’écart dans le contexte d’âge et d’évolution ; ne pas demander ce bilan à toute variante physiologique.',['pa82-genou-orientation','p82-genou'])],
 [('Scoliose : rachis entier debout, première évaluation dans les deux plans, genoux tendus, pieds écartés à la largeur des épaules et compensation de l’inégalité de longueur.','p82-scoliose-radio'),('Mesurer le Cobb sur les plateaux des vertèbres limites les plus inclinées et évaluer le profil sagittal.','p82-scoliose-radio'),('Ne pas assembler deux clichés séparés thoracique et lombaire pour remplacer l’examen global ; utiliser la projection postéro-antérieure lorsque possible pour réduire l’exposition mammaire.',['p82-scoliose-radio','pa82-scoliose-pa'])],
 [('Charcot suspect : radiographies du pied et de la cheville, idéalement bilatérales ; pied face, oblique médiale, profil ; cheville face, mortaise, profil.',['pa82-charcot-r6','pa82-charcot-r7']),('La charge est préférable si réalisable ; sans appui, une malposition peut être moins visible. Une radiographie normale n’exclut pas un Charcot actif.',['pa82-charcot-r7','pa82-charcot-r8']),('Si les clichés sont normaux et la suspicion persiste, réaliser une IRM tout en maintenant l’immobilisation et la décharge.',['pa82-charcot-r8','pa82-charcot-r5'])],
 [('Maillet osseux traité par attelle : profil sous attelle, notamment si le fragment dépasse le tiers de la surface articulaire.','pa82-maillet-os-congruent'),('Vérifier la congruence et l’absence de subluxation palmaire.','pa82-maillet-os-congruent'),('Une articulation congruente peut poursuivre le traitement par attelle ; la taille du fragment ne constitue pas seule une indication opératoire.','pa82-maillet-os-congruent')]
])
p.h('Biologie de l’XLH : ne pas utiliser les normes adultes chez tous les enfants')
p.p('Demander une phosphatémie interprétée selon l’âge, phosphatases alcalines, calcium, parathormone et métabolites de vitamine D selon le bilan spécialisé ; évaluer la réabsorption rénale du phosphate par le TmP/DFG. Une hypophosphatémie avec fuite rénale et calcitriol inapproprié oriente vers le mécanisme FGF23 ; la confirmation génétique précise l’étiologie.', 'p82-xlh-mecanisme-bilan')
p.tableau(['Âge dans le tableau suisse 2024', 'Phosphate plasmatique en mmol/l'], [[(a,'pa82-xlh-phosphate-age'),(v,'pa82-xlh-phosphate-age')] for a,v in [('Moins de trois mois','1,55–2,40'),('Trois à douze mois','1,55–2,20'),('Un à cinq ans','1,45–2,10'),('Six à douze ans','1,16–1,87'),('Treize à dix-huit ans','0,74–1,45'),('Adulte','0,80–1,45')]])
p.p('Ces intervalles sont ceux du tableau de la publication suisse ; la valeur doit être confrontée à la référence pédiatrique adaptée du laboratoire. Une phosphatémie adulte jugée normale n’exclut pas une hypophosphatémie pour un âge où l’intervalle attendu est plus élevé.', ['pa82-xlh-phosphate-age','p82-xlh-mecanisme-bilan'])
p.p('Chez l’enfant, les radiographies du poignet et du genou montrent les anomalies métaphysaires de rachitisme et permettent une cotation RSS. Chez l’adulte, rechercher notamment ostéomalacie, enthésopathies et pseudofractures ; le retentissement radiologique ne suffit pas à nommer le mécanisme génétique.', ['pa82-xlh-imagerie','p82-xlh-clinique','p82-xlh-mecanisme-bilan'])
p.h('9.c — Alternatives et précautions : raisonner sur la modalité et le contraste séparément')
p.fenetre('IRM impossible, enfant et examens à éviter', [
 ('Si une IRM indiquée pour un Charcot suspect est indisponible ou contre-indiquée, IWGDF propose scintigraphie, scanner ou SPECT-CT comme examens d’appui. L’absence immédiate de ces moyens ne doit pas retarder la protection d’un Charcot cliniquement probable.', ['pa82-charcot-r9','p82-charcot']),
 ('Chez l’enfant, l’examen clinique normal d’un pied souple indolore ou d’un rachis normal au scoliomètre permet d’éviter une radiographie sans indication. Quand la scoliose justifie un cliché, le rachis debout et la projection postéro-antérieure répondent à la question avec une attention à l’exposition.', ['pa82-plat-europe-imagerie','pa82-scoliose-normalite','p82-scoliose-radio','pa82-scoliose-pa']),
 ('Le scanner du radius peut préciser une fracture occulte ou aider à la planification opératoire ; il vient après la prise en charge initiale. Il ne doit pas faire attendre le réalignement nécessaire devant une menace cutanée ou neurovasculaire.', ['pa82-radius-imagerie','p82-radius'])])
p.fenetre('Grossesse et allaitement : ne pas confondre IRM et injection', [
 ('Selon ESUR, une IRM avec gadolinium pendant la grossesse ne se justifie que pour une indication très forte, avec la plus petite dose d’un agent macrocyclique. Cette règle concerne l’injection ; elle ne transforme pas chaque examen musculosquelettique en IRM injectée.', 'pa82-esur-gadolinium-grossesse'),
 ('Un produit iodé peut être administré exceptionnellement pendant la grossesse lorsque l’examen radiologique est essentiel ; dans ce contexte, la fonction thyroïdienne du nouveau-né doit être contrôlée durant la première semaine.', 'pa82-esur-iode-grossesse'),
 ('L’allaitement peut se poursuivre après un produit gadoliné macrocyclique selon ESUR. Toutefois, chez une mère enceinte ou allaitante ayant une insuffisance rénale, ESUR indique de ne pas administrer de gadolinium : cette exception doit être recherchée avant de donner la règle générale.', ['pa82-esur-allaitement','pa82-esur-mere-renale'])])
p.fenetre('Insuffisance rénale et réaction antérieure au contraste', [
 ('Un DFGe inférieur à 30 ml/min/1,73 m² constitue un facteur de risque lors d’une injection intraveineuse de contraste iodé ou d’une injection intra-artérielle avec second passage rénal. Envisager une méthode sans injection iodée si elle répond à la question diagnostique.', ['pa82-esur-renal','pa82-esur-alternative']),
 ('Devant une réaction antérieure à un produit iodé ou gadoliné, envisager une modalité différente ou un examen sans injection si le rendement diagnostique reste suffisant. L’antécédent doit désigner le produit et la réaction ; une étiquette imprécise ne remplace pas cette analyse.', 'pa82-esur-hypersensibilite'),
 ('Chez une mère enceinte ou allaitante insuffisante rénale, les précautions relatives au contraste iodé suivent le cadre de prévention des lésions rénales associées au contraste ; pour le gadolinium, la recommandation ESUR est l’absence d’administration.', 'pa82-esur-mere-renale')])
p.h('9.d — Deuxième intention et résultats qui changent la priorité')
p.p('Pour une scoliose, l’IRM ambulatoire est indiquée notamment devant douleur persistante au-delà de six à douze semaines, anomalie neurologique inexpliquée, courbure atypique ou suspicion de malformation ; elle couvre la jonction craniocervicale jusqu’au sacrum. Avant chirurgie, la publication suisse recommande une IRM complète même en l’absence de signe neurologique.', 'p82-scoliose-irm')
p.p('L’arthrose de la main appelle une imagerie ciblée selon l’articulation, la localisation et le type de lésion recherchée. Dupuytren n’exige habituellement pas d’examen supplémentaire ; en demander seulement pour une comorbidité pertinente ou un autre diagnostic évite de confondre confirmation clinique et dépistage non ciblé.', ['p82-arthrose-diagnostic','pa82-dupuytren-examens'])
p.p('Si l’articulation douloureuse est suspecte d’infection, la ponction recherche surtout l’identification bactérienne, avec analyse cellulaire. En dehors d’un sepsis, les prélèvements diagnostiques précèdent l’antibiothérapie empirique afin de limiter les cultures faussement négatives ; un sepsis ou un choc impose une prise en charge immédiate.', ['pa82-arthrite-ponction','pa82-arthrite-suspecte'])
p.p('Pour un Charcot sur peau intacte, des marqueurs inflammatoires normaux ne constituent pas un test d’exclusion. Le résultat qui change le parcours est la combinaison clinique-imagerie, avec IRM si les radiographies restent normales et suspicion persistante ; la protection du pied reste engagée pendant ce bilan.', ['pa82-charcot-r10','pa82-charcot-r8','pa82-charcot-r5'])
p.sauver()
